export function createBootstrapAssets(){
 const width=256,height=128,pixels=new Uint8Array(width*height),glyphs={};let index=0;
 for(const [char,bitmap]of Object.entries(rows)){
  const x=index%16*14,y=Math.floor(index/16)*18;index++;
  for(let row=0;row<7;row++)for(let col=0;col<5;col++)if(bitmap[row][col]==='1')for(let dy=0;dy<2;dy++)for(let dx=0;dx<2;dx++)pixels[(y+row*2+2+dy)*width+x+col*2+2+dx]=255;
  glyphs[char]={x,y,w:14,h:18,left:-1,top:-1,advance:12};if(/[A-Z]/.test(char))glyphs[char.toLowerCase()]=glyphs[char];
 }
 return {pixels,metrics:{format:'sdf-r8-v1',width,height,size:16,spread:1,ascent:0,sha256:'bootstrap-pixel-alphabet',glyphs}};
}
